// #63e34a (b6eac71496158ecc2463e34a) «BUG · כותרת המסך נחתכת בזום 200%…» — עבר QA 08.11 (веб 195 px + Android).
//   AC: «בזום 200% … הכותרת של /prayers, /zmanim, /tehilim/[chapter] ו-/profile מוצגת במלואה ואינה נחתכת לשלוש נקודות».
// #ebcfa6 (a1d3cc727e7ecdd64febcfa6, №27) — Android: «היסטוריית התפילות שלי» рвалась «היסטו / ריית ה / תפילות / שלי»; עבר QA 09.11.
//   מה רצוי: «בזום 200% הכותרת נשברת לשורות רק בין מילים (כמו «זמני / תפילות» ו-«שיעורי / תורה»)».
// Факт 08.11/09.11 (Pixel 6, wm density 840, шрифт 1.15): все заголовки целиком, переносы только между словами; истории — «היסטוריית / התפילות שלי».
// Кейсы: .qa/tests/zoom-200/Z2-01-screen-titles.md, Z2-04-history-title.md. Только просмотр. Плотность возвращается в after().
import { driver, expect } from '@wdio/globals';
import { goTab } from '../../helpers/nav.ts';
import { tapLabel } from '../../helpers/ui.ts';
import { goHome, openProfile, openZmanim } from '../_lib/readiness-1910.ts';
import { openTehilimChapter, skipWith } from '../_lib/app-0710.ts';
import { openHistoryFromHome, HISTORY_TITLE } from '../_lib/app-2110.ts';
import {
  zoomOn, zoomOff, textNode, insideScreenX, linesAtZoom, wordCount, notTruncated, saveShot,
} from '../_lib/app-0911.ts';

type Screen = { title: string; open: () => Promise<void>; shot: string };
const SCREENS: Screen[] = [
  { title: 'תפילות', open: async () => { await goHome(); await goTab('תפילות'); }, shot: 'q27-prayers.png' },
  { title: 'זמני תפילות', open: openZmanim, shot: 'q27-zmanim.png' },
  { title: 'תהילים ג׳', open: () => openTehilimChapter(3), shot: 'q27-tehilim-3.png' },
  { title: 'פרופיל אישי', open: openProfile, shot: 'q27-profile.png' },
  { title: 'שיעורי תורה', open: async () => { await goHome(); await goTab('תפילות'); await tapLabel('שיעורי תורה, השיעורים הזמינים לקריאה'); }, shot: 'q27-lessons.png' },
  { title: HISTORY_TITLE, open: openHistoryFromHome, shot: 'q27-history.png' },
];

/** Заголовок — верхняя треть экрана. */
async function titleNode(title: string) {
  const { height } = await driver.getWindowSize();
  return textNode(title, (n) => n.y < height * 0.33);
}

describe('09.11 — зум 200% (Android): заголовки экранов (#63e34a, #ebcfa6)', () => {
  before(function () { if (!driver.isAndroid) skipWith(this, 'зум через wm density — только Android'); });
  after(async () => { if (driver.isAndroid) await zoomOff(); });

  it('Z2-01/Z2-04 При wm density 840 заголовки «תפילות», «זמני תפילות», «תהילים ג׳», «פרופיל אישי», «שיעורי תורה», «היסטוריית התפילות שלי» — целиком, в экране, строк не больше, чем слов #63e34a #ebcfa6 @android @prod-safe @manual-check', async () => {
    // 1. Обычная плотность: высота одной строки каждого заголовка (по тикетам в обычном размере — одна строка).
    const normal: Record<string, Awaited<ReturnType<typeof titleNode>>> = {};
    for (const s of SCREENS) { await s.open(); normal[s.title] = await titleNode(s.title); }

    // 2. Зум 200%.
    await goHome();
    await zoomOn();

    for (const s of SCREENS) {
      await s.open();
      const z = await titleNode(s.title);
      await saveShot(s.shot);
      const lines = linesAtZoom(z.h, normal[s.title].h);
      console.log(`[Q-27] «${s.title}»: ${z.w}×${z.h} (обычн. ${normal[s.title].w}×${normal[s.title].h}) → ~${lines} строк(и)`);
      // Ожидаемо (AC #63e34a / מה רצוי #ebcfa6): заголовок весь в экране, не обрезан, разрывы только между словами.
      expect(await insideScreenX(z)).toBe(true);
      expect(notTruncated(z, normal[s.title])).toBe(true);
      expect(lines).toBeLessThanOrEqual(wordCount(s.title));
    }
    // Глазами по скринам qa-0911/q27-*.png: нет «…», слово не разорвано (истории — «היסטוריית / התפילות שלי»).
  });
});
